<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$url=fn($p)=>html_entity_decode($this->uri($p,'systemmanagement'),ENT_QUOTES,'UTF-8');$icons=$this->getObject('iconservice','ui');$hidden='<input type="hidden" name="csrf_token" value="'.$e($systemCsrf).'">'; ?>
<main class="chisimba-workspace chisimba-flow system-management"><header class="chisimba-page-header chisimba-card"><div><p class="chisimba-eyebrow">Site administration</p><h1>System management</h1><p>Plan service interruptions and communicate clearly with the people who use this site.</p></div></header>
<?php if($systemMessage):?><div class="chisimba-notice chisimba-notice--success" role="status"><?php echo $e($systemMessage);?></div><?php endif;?><?php if($systemError):?><div class="chisimba-notice chisimba-notice--error" role="alert"><?php echo $e($systemError);?></div><?php endif;?>
<section class="system-management__grid"><article class="chisimba-card"><h2><?php echo $icons->render('power',array('decorative'=>true));?> Maintenance mode</h2><p><strong>Status: <?php echo $systemMaintenance['active']?'Offline for non-administrators':'Online';?></strong></p><p>Planned dates are advisory and never take the site offline automatically. Only the manual control below changes availability. Administrators always retain access.</p><p>The maintenance email will quote this planned window; it will not have a separate date selector.</p><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'save')));?>"><?php echo $hidden;?><input type="hidden" name="kind" value="maintenance"><div class="chisimba-form-field"><label for="maintenance-message">Offline message</label><textarea id="maintenance-message" name="message" rows="4" required><?php echo $e($systemMaintenance['message']);?></textarea></div><div class="system-management__dates"><div class="chisimba-form-field"><label for="maintenance-start">Planned start</label><input id="maintenance-start" name="start" type="datetime-local" value="<?php echo $e($systemService->storageToLocal($systemMaintenance['start']));?>"></div><div class="chisimba-form-field"><label for="maintenance-end">Planned end</label><input id="maintenance-end" name="end" type="datetime-local" value="<?php echo $e($systemService->storageToLocal($systemMaintenance['end']));?>"></div></div><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $icons->render('save',array('decorative'=>true));?> Save plan</button></div></form><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'setmaintenance')));?>"><?php echo $hidden;?><input type="hidden" name="state" value="<?php echo $systemMaintenance['active']?'online':'offline';?>"><div class="chisimba-form-actions"><button class="button chisimba-state-action <?php echo $systemMaintenance['active']?'chisimba-state-action--offline':'chisimba-state-action--online';?>" type="submit"><?php echo $icons->render($systemMaintenance['active']?'power-off':'power',array('decorative'=>true));?> <?php echo $systemMaintenance['active']?'Bring site online':'Take site offline';?></button></div></form></article>
<article class="chisimba-card"><h2><?php echo $icons->render('mail',array('decorative'=>true));?> Send maintenance email</h2><p>This sends immediately and automatically includes the planned maintenance start and end shown alongside. It does not take the site offline.</p><form class="chisimba-form" method="post" action="<?php echo $e($url(array('action'=>'sendmaintenanceemail')));?>" data-maintenance-email><?php echo $hidden;?><div class="chisimba-form-field"><label for="email-audience">Audience</label><select id="email-audience" name="audience"><option value="everyone">Everyone (<?php echo (int)$systemAudienceCounts['everyone'];?>)</option><option value="admins">Administrators (<?php echo (int)$systemAudienceCounts['admins'];?>)</option><option value="lecturers">Lecturers (<?php echo (int)$systemAudienceCounts['lecturers'];?>)</option><option value="students">Students (<?php echo (int)$systemAudienceCounts['students'];?>)</option></select></div><div class="chisimba-form-field"><label for="email-subject">Subject</label><input id="email-subject" name="subject" maxlength="255" value="Scheduled maintenance" required></div><div class="chisimba-form-field"><label for="email-message">Message</label><textarea id="email-message" name="email_message" rows="7" required><?php echo $e($systemMaintenance['message']);?></textarea></div><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $icons->render('send',array('decorative'=>true));?> Send email notice</button></div></form></article></section></main>
